#!/usr/bin/env python
"""Conventional MD. Generated by md-openmm; edit freely -- nothing regenerates this file.

Reads ../md.config.yaml and the system built by `md-openmm sys-gen`. Every path is relative to
this script, so moving `inputs/` and `MD/` together to another machine changes nothing.

Restarting: run it again. If `production.chk` exists the run continues from it, and the reporters
append rather than truncate.
"""
import os
import sys
from pathlib import Path

import yaml
from openmm import (LangevinMiddleIntegrator, MonteCarloBarostat, Platform, XmlSerializer,
                    unit)
from openmm.app import (CheckpointReporter, DCDFile, PDBFile, Simulation, StateDataReporter)

HERE = Path(__file__).resolve().parent
CONFIG = yaml.safe_load((HERE.parent / "md.config.yaml").read_text())
INPUTS = (HERE.parent / CONFIG["paths"]["inputs_folder"]).resolve()

common = CONFIG["common"]
method = CONFIG["cMD"]
implicit = common.get("pressure_bar") is None

TEMPERATURE = float(common["temperature_kelvin"]) * unit.kelvin
TIMESTEP = float(common["timestep_fs"]) * unit.femtoseconds
FRICTION = float(common["friction_per_ps"]) / unit.picosecond
SEED = common.get("random_seed")


def steps_for(picoseconds):
    exact = picoseconds * 1000.0 / float(common["timestep_fs"])
    if abs(exact - round(exact)) > 1e-9:
        raise SystemExit(
            f"{picoseconds} ps is not a whole number of {common['timestep_fs']} fs steps "
            f"({exact}). Rounding would run a different length than the configuration says.")
    return int(round(exact))


def make_simulation(system, topology, platform_name=None):
    integrator = LangevinMiddleIntegrator(TEMPERATURE, FRICTION, TIMESTEP)
    if SEED is not None:
        integrator.setRandomNumberSeed(int(SEED) % (2 ** 31 - 1))
    if platform_name:
        platform = Platform.getPlatformByName(platform_name)
        properties = {}
        if platform_name == "CUDA":
            properties = {"Precision": "mixed"}
            device = os.environ.get("MD_DEVICE")
            if device:
                properties["DeviceIndex"] = str(device)
        return Simulation(topology, system, integrator, platform, properties)
    return Simulation(topology, system, integrator)


def main():
    platform_name = os.environ.get("MD_PLATFORM") or None
    pdb = PDBFile(str(INPUTS / "topology.pdb"))
    system = XmlSerializer.deserialize((INPUTS / "system.xml").read_text())

    if not implicit:
        # NPT: exactly one barostat, added here rather than baked into system.xml so the same
        # system can be run at another pressure without rebuilding it.
        barostat = MonteCarloBarostat(float(common["pressure_bar"]) * unit.bar, TEMPERATURE, 25)
        if SEED is not None:
            barostat.setRandomNumberSeed((int(SEED) + 1) % (2 ** 31 - 1))
        system.addForce(barostat)

    simulation = make_simulation(system, pdb.topology, platform_name)
    checkpoint = HERE / "production.chk"
    resuming = checkpoint.is_file()

    if resuming:
        simulation.loadCheckpoint(str(checkpoint))
        done = simulation.context.getStepCount()
        print(f"[cMD] resuming from {checkpoint.name} at step {done:,}")
    else:
        state = XmlSerializer.deserialize((INPUTS / "initial_state.xml").read_text())
        simulation.context.setState(state)
        done = 0
        print(f"[cMD] minimising, max {CONFIG['minimization']['max_iterations']} iterations")
        simulation.minimizeEnergy(maxIterations=int(CONFIG["minimization"]["max_iterations"]))
        simulation.context.setVelocitiesToTemperature(TEMPERATURE,
                                                      int(SEED) if SEED is not None else 0)
        equilibration = CONFIG["equilibration"]
        nvt = steps_for(float(equilibration.get("nvt_duration_ps") or 0))
        npt = steps_for(float(equilibration.get("npt_duration_ps") or 0))
        if nvt:
            print(f"[cMD] equilibrating {equilibration['nvt_duration_ps']} ps")
            simulation.step(nvt)
        if npt and not implicit:
            print(f"[cMD] equilibrating {equilibration['npt_duration_ps']} ps with the barostat")
            simulation.step(npt)
        simulation.context.setStepCount(0)

    total = steps_for(float(method["duration_ns"]) * 1000.0)
    remaining = total - done
    if remaining <= 0:
        print(f"[cMD] already complete: {done:,} of {total:,} steps")
        return 0

    append = resuming
    simulation.reporters.append(CheckpointReporter(
        str(checkpoint), steps_for(float(method["checkpoint_interval_ps"]))))
    simulation.reporters.append(StateDataReporter(
        str(HERE / "production.csv"), steps_for(float(method["solute_interval_ps"])),
        step=True, time=True, potentialEnergy=True, temperature=True,
        volume=not implicit, speed=True, append=append))
    simulation.reporters.append(StateDataReporter(
        sys.stdout, steps_for(float(method["whole_system_interval_ps"])),
        step=True, time=True, potentialEnergy=True, temperature=True, speed=True))

    dcd_path = HERE / "production.dcd"
    dcd_mode = "r+b" if (append and dcd_path.is_file()) else "wb"
    dcd_file = open(dcd_path, dcd_mode)
    dcd = DCDFile(dcd_file, pdb.topology, TIMESTEP,
                  firstStep=done, interval=steps_for(float(method["whole_system_interval_ps"])),
                  append=(dcd_mode == "r+b"))

    print(f"[cMD] {method['ensemble']}, {remaining:,} of {total:,} steps "
          f"({method['duration_ns']} ns at {common['timestep_fs']} fs)")
    interval = steps_for(float(method["whole_system_interval_ps"]))
    written = 0
    while written < remaining:
        chunk = min(interval, remaining - written)
        simulation.step(chunk)
        state = simulation.context.getState(getPositions=True,
                                            enforcePeriodicBox=not implicit)
        dcd.writeModel(state.getPositions(), periodicBoxVectors=(
            None if implicit else state.getPeriodicBoxVectors()))
        written += chunk
    dcd_file.close()

    simulation.saveCheckpoint(str(checkpoint))
    final = simulation.context.getState(getPositions=True, getVelocities=True)
    (HERE / "final_state.xml").write_text(XmlSerializer.serialize(final))
    print(f"[cMD] complete: {simulation.context.getStepCount():,} steps")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
